@php
    $assistantUser = auth()->user();
    $assistantVisible = $assistantUser instanceof \App\Models\User
        && app(\App\Services\Authorization\AiAssistantAuthorization::class)->allows($assistantUser, \App\Enums\AiAssistantPermission::Use)
        && app(\App\Services\AiAssistant\AiAssistantSettings::class)->enabled();
@endphp
@if ($assistantVisible)
<div x-data="tpzAssistant()" x-init="init()" class="tpz-ai-root" wire:ignore @keydown.escape.window="if (deletePendingId !== null) cancelDelete(); else if (editingConversationId !== null) cancelRename()">
    <button x-show="!open" @click="open=true; load()" class="tpz-ai-launcher" aria-label="Open TPZ AI Assistant"><span aria-hidden="true">✦</span><span>TPZ AI Assistant</span></button>
    <section x-cloak x-show="open" :class="{'tpz-ai-full':full}" class="tpz-ai-panel" role="dialog" aria-label="TPZ AI Assistant">
        <header class="tpz-ai-header"><div class="tpz-ai-brand"><span class="tpz-ai-mark" aria-hidden="true">✦</span><span><strong>TPZ AI Assistant</strong><small x-text="provider === 'mock' ? 'Demo mode · Read-only ERP data' : (available ? 'Connected to authorized ERP data' : 'OpenAI unavailable · API key not configured')"></small></span></div><div class="tpz-ai-controls"><button @click="newChat()" title="New conversation" aria-label="New conversation">＋</button><button @click="full=!full; historyOpen=full" :title="full?'Restore window':'Expand to full screen'" aria-label="Expand or restore">□</button><button @click="open=false" title="Minimize" aria-label="Minimize">−</button><button @click="close()" title="Close" aria-label="Close">×</button></div></header>
        <div class="tpz-ai-toolbar"><button class="tpz-ai-sidebar-toggle" @click="historyOpen=!historyOpen" :aria-expanded="historyOpen">☰ <span>History</span></button><span class="tpz-ai-demo" x-show="provider==='mock'">MOCK DEMONSTRATION</span><button @click="newChat()">＋ New chat</button></div>
        <div class="tpz-ai-layout" :class="{'tpz-ai-expanded':full,'history-hidden':!historyOpen}"><button x-cloak x-show="historyOpen && (!full || window.matchMedia('(max-width: 640px)').matches)" class="tpz-ai-history-scrim" type="button" @click="historyOpen=false" aria-label="Close conversation history"></button>
            <aside class="tpz-ai-history" aria-label="Conversation history"><template x-for="item in conversations" :key="item.id"><div class="tpz-ai-history-row"><button @click="select(item.id)" :class="{'active':item.id===conversationId}" x-text="item.title"></button><button class="tpz-ai-rename" @click="startRename(item)" title="Rename conversation" aria-label="Rename conversation">✎</button><button class="tpz-ai-delete" @click="requestDelete(item.id)" title="Delete conversation" aria-label="Delete conversation">×</button><form x-cloak x-show="editingConversationId === item.id" class="tpz-ai-inline-rename" @submit.prevent="saveRename(item)"><input x-model="editingTitle" maxlength="160" aria-label="New conversation name" @keydown.escape.stop.prevent="cancelRename()"><div class="tpz-ai-inline-actions"><button type="submit">Save</button><button type="button" @click="cancelRename()">Cancel</button></div></form></div></template><p x-show="conversations.length===0" class="tpz-ai-empty-history">Your conversations will appear here.</p></aside>
            <div class="tpz-ai-main"><div class="tpz-ai-messages" x-ref="messages" aria-live="polite">
                <template x-if="messages.length===0"><div class="tpz-ai-welcome"><div class="sparkle">✦</div><strong>How can I help with your ERP?</strong><p>Answers use authorized TPZ reports. Demonstration mode is labelled.</p><div class="tpz-ai-suggestions"><button @click="suggest('What are today’s sales orders?')">Today’s orders</button><button @click="suggest('Show current product inventory')">Inventory</button><button @click="suggest('Show customer returns awaiting QC')">Returns awaiting QC</button><button @click="suggest('Show pending stock requests')">Pending requests</button></div></div></template>
                <template x-for="message in messages" :key="message.id || message.localId"><article x-cloak x-show="message.role==='user' || message.content || message.status!=='streaming' || !busy" :class="message.role==='user'?'user':'assistant'" class="tpz-ai-bubble"><div class="tpz-ai-avatar" x-text="message.role==='user'?'You':'✦'"></div><div class="tpz-ai-message-content"><div x-show="message.content" x-html="message.role==='assistant'?safeMarkdown(message.content):escapeHtml(message.content)"></div><p x-show="message.role==='assistant' && !message.content && message.status==='failed'" class="tpz-ai-empty-failure">The assistant could not complete this reply.</p><p x-show="message.role==='assistant' && !message.content && message.status==='stale'" class="tpz-ai-empty-failure">This earlier response may have been interrupted. Refresh to check its status.</p><p x-show="message.role==='assistant' && !message.content && message.status==='interrupted'" class="tpz-ai-empty-failure">Generation was stopped before an answer appeared.</p></div><div class="tpz-ai-message-actions"><small x-show="message.status==='interrupted'">Generation stopped · partial answer</small><small x-show="busy && message === messages.at(-1) && message.status==='streaming' && Boolean(message.content)" x-text="stageMessage"></small><button x-show="message.role==='assistant' && (message.status==='complete'||message.status==='interrupted')" @click="copy(message.content)">Copy</button><button x-show="message === messages.at(-1) && (message.status==='failed' || (message.status==='interrupted' && !message.content))" @click="retry()">Retry question</button></div></article></template>
                <div x-show="busy && !hasCurrentAssistantText()" class="tpz-ai-progress"><i></i><span x-text="stageMessage || 'Preparing your response…'"></span></div><div x-show="error" class="tpz-ai-error" role="alert" x-text="error"></div>
            </div><details x-cloak x-show="links.length" class="tpz-ai-shortcuts"><summary>ERP shortcuts</summary><div class="tpz-ai-links"><template x-for="link in links" :key="link.url"><a :href="link.url" x-text="link.label"></a></template></div></details><form class="tpz-ai-composer" @submit.prevent="send()"><textarea x-ref="input" x-model="draft" @keydown.enter="onEnter($event)" placeholder="Ask TPZ AI Assistant…" rows="1" maxlength="6000" aria-label="Message TPZ AI Assistant"></textarea><button x-show="!busy" type="submit" :disabled="!draft.trim()" aria-label="Send message">➤</button><button x-show="busy" type="button" class="tpz-ai-stop" @click="stop()" aria-label="Stop generation">■</button></form><small class="tpz-ai-foot">Read-only · ERP permissions apply · Verify important figures</small></div>
        </div>
        <div x-cloak x-show="deletePendingId !== null" class="tpz-ai-modal-backdrop"><div class="tpz-ai-confirm-dialog" role="alertdialog" aria-modal="true" aria-labelledby="tpz-ai-confirm-title" aria-describedby="tpz-ai-confirm-message"><strong id="tpz-ai-confirm-title">Delete conversation?</strong><p id="tpz-ai-confirm-message">This conversation and its messages will be permanently deleted.</p><div class="tpz-ai-confirm-actions"><button type="button" @click="cancelDelete()">Cancel</button><button type="button" class="is-danger" @click="confirmDelete()">Delete</button></div></div></div>
    </section>
</div>
<script>
function tpzEscapeHtml(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function tpzSafeMarkdown(value){const escaped=tpzEscapeHtml(value);const inline=s=>s.replace(/`([^`\n]+)`/g,'<code>$1</code>').replace(/\*\*([^*\n]+)\*\*/g,'<strong>$1</strong>').replace(/\*([^*\n]+)\*/g,'<em>$1</em>');const lines=escaped.split(/\r?\n/);let out='',list=null,table=false;const close=()=>{if(list){out+=list==='ul'?'</ul>':'</ol>';list=null}if(table){out+='</tbody></table>';table=false}};for(const line of lines){const trimmed=line.trim();if(!trimmed){close();continue}const heading=trimmed.match(/^(#{1,3})\s+(.+)$/);if(heading){close();const level=heading[1].length;out+=`<h${level}>${inline(heading[2])}</h${level}>`;continue}if(/^\|.*\|$/.test(trimmed)){const cells=trimmed.slice(1,-1).split('|').map(x=>x.trim());if(cells.every(x=>/^:?-{3,}:?$/.test(x)))continue;if(!table){close();out+='<table><tbody>';table=true}out+='<tr>'+cells.map(x=>`<td>${inline(x)}</td>`).join('')+'</tr>';continue}const bullet=trimmed.match(/^[-*]\s+(.+)$/),number=trimmed.match(/^\d+\.\s+(.+)$/);if(bullet||number){const kind=bullet?'ul':'ol';if(list!==kind){close();list=kind;out+=`<${kind}>`}out+=`<li>${inline((bullet||number)[1])}</li>`;continue}close();out+=`<p>${inline(trimmed)}</p>`}close();return out}
function tpzAssistant(){return {open:false,full:false,historyOpen:false,editingConversationId:null,editingTitle:'',deletePendingId:null,busy:false,error:'',draft:'',provider:'mock',available:true,conversationId:null,conversations:[],messages:[],links:[],lastPrompt:'',stageMessage:'',controller:null,requestStarted:0,firstDeltaAt:null,init(){},escapeHtml:tpzEscapeHtml,safeMarkdown:tpzSafeMarkdown,async load(){try{const r=await fetch('/admin/ai-assistant',{headers:{Accept:'application/json'}});if(!r.ok)throw Error();const d=await r.json();this.conversations=d.conversations;this.links=d.links||[];this.provider=d.settings.provider;this.available=d.settings.available;if(!this.available)this.error='OpenAI is unavailable because the server API key is not configured.';if(!this.conversationId&&this.conversations.length)await this.select(this.conversations[0].id);else if(!this.conversationId)await this.newChat()}catch(e){this.error='Assistant is unavailable. Please refresh or try again.'}},headers(){return {Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]')?.content||''}},async list(){const r=await fetch('/admin/ai-assistant',{headers:{Accept:'application/json'}});if(r.ok){const d=await r.json();this.conversations=d.conversations;this.links=d.links||[]}},async newChat(){if(this.busy){this.error='Stop the current reply before starting a new chat.';return}const r=await fetch('/admin/ai-assistant/conversations',{method:'POST',headers:this.headers()});if(!r.ok){this.error='Could not start a new chat.';return}this.conversationId=(await r.json()).conversation.id;this.messages=[];if(!this.full)this.historyOpen=false;this.error=this.available?'':'OpenAI is unavailable because the server API key is not configured.';await this.list();this.$nextTick(()=>this.$refs.input?.focus())},startRename(item){this.editingConversationId=item.id;this.editingTitle=item.title;this.error=''},cancelRename(){this.editingConversationId=null;this.editingTitle=''},async saveRename(item){const title=this.editingTitle.trim();if(!title||title.length>160){this.error='Conversation name must be between 1 and 160 characters.';return}try{const r=await fetch('/admin/ai-assistant/conversations/'+item.id,{method:'PATCH',headers:this.headers(),body:JSON.stringify({title})});if(!r.ok)throw Error();const d=await r.json();item.title=d.conversation.title;this.cancelRename()}catch(e){this.error='Could not rename the conversation.'}},requestDelete(id){this.deletePendingId=id},cancelDelete(){this.deletePendingId=null},async confirmDelete(){const id=this.deletePendingId;if(id===null)return;this.cancelDelete();try{const r=await fetch('/admin/ai-assistant/conversations/'+id,{method:'DELETE',headers:this.headers()});if(!r.ok)throw Error();if(this.conversationId===id){this.conversationId=null;this.messages=[]}await this.list();if(this.conversationId===null&&this.conversations.length)await this.select(this.conversations[0].id)}catch(e){this.error='Could not delete the conversation.'}},async close(){if(this.busy)this.stop();this.open=false;this.full=false},async select(id){if(this.busy){this.error='Stop the current reply before switching conversations.';return}if(!this.full)this.historyOpen=false;this.conversationId=id;this.error='';const r=await fetch('/admin/ai-assistant/conversations/'+id,{headers:{Accept:'application/json'}});if(!r.ok){this.error='Conversation could not be loaded.';return}this.messages=(await r.json()).messages.map(m=>m.role==='assistant'&&m.status==='streaming'?{...m,status:'stale'}:m);this.scroll()},async suggest(text){this.draft=text;await this.send()},onEnter(event){if(!event.shiftKey){event.preventDefault();this.send()}},hasCurrentAssistantText(){const current=this.messages.at(-1);return current?.role==='assistant'&&current.status==='streaming'&&Boolean(current.content)},async send(retry=false){if(this.busy)return;if(!retry){this.lastPrompt=this.draft.trim();if(!this.lastPrompt)return;this.messages.push({role:'user',content:this.lastPrompt,localId:Date.now()});this.draft=''}this.error='';this.stageMessage='Understanding your question…';this.messages.push({role:'assistant',content:'',status:'streaming',localId:Date.now()+1});const item=this.messages.at(-1);this.busy=true;this.controller=new AbortController();this.requestStarted=performance.now();this.firstDeltaAt=null;this.scroll();try{const response=await fetch('/admin/ai-assistant/conversations/'+this.conversationId+'/messages',{method:'POST',headers:this.headers(),body:JSON.stringify({message:this.lastPrompt}),signal:this.controller.signal});if(!response.ok)throw Error();const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';while(true){const {value,done}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});const parts=buffer.split(/\r?\n\r?\n/);buffer=parts.pop();for(const part of parts){const line=part.split(/\r?\n/).find(x=>x.startsWith('data:'));if(!line)continue;const event=JSON.parse(line.slice(5).trim());if(event.type==='delta'){if(this.firstDeltaAt===null)this.firstDeltaAt=performance.now();item.content+=event.text;this.scroll()}if(event.type==='stage')this.stageMessage=event.message;if(event.type==='done'){item.status='complete';item.id=event.message_id;item.metrics=event.metrics;item.clientMetrics={requestStartToFirstTokenMs:this.firstDeltaAt===null?null:Math.round(this.firstDeltaAt-this.requestStarted),totalClientMs:Math.round(performance.now()-this.requestStarted)}}if(event.type==='error'){this.error=event.message;throw Error()}}}if(item.status==='streaming')throw Error();await this.list()}catch(e){if(e.name==='AbortError'){item.status='interrupted';this.error='Generation stopped. Any partial text is kept; budget usage remains reserved if the provider may have processed it.'}else{item.status=item.content?'interrupted':'failed';if(!this.error)this.error='TPZ AI Assistant could not complete this reply. You can retry the question.'}}finally{this.busy=false;this.controller=null;this.scroll()}},stop(){if(this.controller)this.controller.abort()},async retry(){if(this.busy)return;const last=this.messages.at(-1);if(last?.role!=='assistant'||!['failed','interrupted'].includes(last.status))return;const previous=this.messages.slice(0,-1).reverse().find(m=>m.role==='user'&&m.content);if(!previous){this.error='Previous question is unavailable. Please enter it again.';return}this.messages.pop();this.draft=previous.content;await this.send()},async copy(text){try{await navigator.clipboard.writeText(text)}catch(e){this.error='Could not copy this response.'}},scroll(){this.$nextTick(()=>{const el=this.$refs.messages;if(el)el.scrollTop=el.scrollHeight})}}}
</script>
@endif
